          callback();\r\n                }\r\n\r\n                return true;\r\n            },\r\n            Cancel: function () {\r\n                $(this).dialog('close');\r\n                return false;\r\n            }\r\n        },\r\n        minHeight: 50,\r\n        dialogClass: 'modal-shadow'\r\n    };\r\n\r\n    let $confirm = $.getOrCreateDialog('confirm');\r\n    // set message\r\n    $('p', $confirm).html(message);\r\n    // init dialog\r\n    $confirm.dialog($.extend({}, defaults, options));\r\n}\r\n\r\nfunction alert(message, callback) {\r\n    const defaults = {\r\n        title: 'SMSHRM',\r\n        modal: true,\r\n        resizable: false,\r\n        buttons: {\r\n            OK: function () {\r\n                $(this).dialog('close');\r\n                if (callback) callback();\r\n                return false;\r\n            }\r\n        },\r\n        minHeight: 50,\r\n        dialogClass: 'modal-shadow'\r\n    };\r\n\r\n    let $alert = $.getOrCreateDialog('alert');\r\n    // set message\r\n    $('p', $alert).html(message);\r\n    // init dialog\r\n    $alert.dialog($.extend({}, defaults));\r\n}\r\n\r\nfunction updateTableHeaders() {\r\n    if ($('.persist-area').val() !== undefined) {\r\n        let widthspace = $('.persist-area').width() + 18;\r\n        widthspace = widthspace - 17;\r\n        if (widthspace < 1051) {\r\n            widthspace = 1051;\r\n        }\r\n\r\n        $('.floatingHeader').width(widthspace);\r\n\r\n        const isShowLeftMenu = $('#toggle-left-navigation').hasClass('large-next');\r\n\r\n        $('.persist-area').each(function () {\r\n            const el = $(this);\r\n            const offset = el.offset();\r\n            const scrollTop = $(window).scrollTop();\r\n            let floatingHeader = $('.floatingHeader', this);\r\n            if ((scrollTop > offset.top - 60) && (scrollTop < offset.top + el.height())) {\r\n                if (!isShowLeftMenu) {\r\n                    floatingHeader.css({\r\n                        'visibility': 'visible'\r\n                    });\r\n                } else {\r\n                    floatingHeader.css({\r\n                        'visibility': 'visible'\r\n                    });\r\n                }\r\n            } else {\r\n                floatingHeader.css({\r\n                    'visibility': 'hidden'\r\n                });\r\n            }\r\n        });\r\n\r\n        let i = 0;\r\n        $('table.persist-area thead th').each(function () {\r\n            let x = $(this).width();\r\n            $($('table.persist-area .floatingHeader th')[i]).width(x);\r\n            i++;\r\n        });\r\n    }\r\n}\r\n\r\nfunction floatingHeader() {\r\n    let clonedHeaderRow;\r\n    $('.persist-area').each(function () {\r\n        clonedHeaderRow = $('thead', this);\r\n        clonedHeaderRow\r\n            .before(clonedHeaderRow.clone())\r\n            .css('width', clonedHeaderRow.width())\r\n            .addClass('floatingHeader');\r\n    });\r\n\r\n    $('.content_scroll')\r\n        .scroll(updateTableHeaders)\r\n        .trigger('scroll');\r\n    $(window).resize(function () {\r\n        updateTableHeaders();\r\n    });\r\n}\r\n\r\nfunction blockUI() {\r\n    document.getElementById('loadingProcess').style.display = 'block';\r\n}\r\n\r\nfunction unblockUI() {\r\n    document.getElementById('loadingProcess').style.display = 'none';\r\n}\r\n\r\nfunction toastOptions() {\r\n    return {\r\n        tapToDismiss: false,\r\n        closeButton: true,\r\n        progressBar: true,\r\n        positionClass: 'toast-top-center',\r\n        showDuration: 0,\r\n        hideDuration: 0,\r\n        timeOut: 3000,\r\n        extendedTimeOut: 0,\r\n        closeOnHover: false,\r\n        preventDuplicates: true,\r\n        closeHtml: '<button type=\"button\">x</button>'\r\n    };\r\n}\r\n\r\nfunction axiosError(error) {\r\n    if (error.response) {\r\n        let url;\r\n\r\n        switch (error.response.status) {\r\n            case 401:\r\n                url = 'auth/login';\r\n                break;\r\n\r\n            case 404:\r\n                url = 'error/PageNotFound';\r\n                break;\r\n\r\n            case 405:\r\n                url = 'error/AccessDenied';\r\n                break;\r\n\r\n            case 500:\r\n                url = 'error/InternalError';\r\n                break;\r\n        }\r\n\r\n        window.location = _global.root + url;\r\n    }\r\n}\r\n\r\nexport { showMessage, fadeOutMessage, confirm, alert, updateTableHeaders, floatingHeader, blockUI, unblockUI, toastOptions, axiosError };","import $ from 'jquery/dist/jquery';\r\nimport { updateTableHeaders } from './shared/common.functions';\r\n\r\n$(document).ready(function () {\r\n    function toggleLeftNavigation(isShow) {\r\n        let currentElement = $('#toggle-left-navigation');\r\n\r\n        if (isShow) {\r\n            currentElement.removeClass('large-next');\r\n            currentElement.addClass('large-back');\r\n            currentElement.attr({ title: 'Hide Left Navigation' });\r\n            $('#left-navigation').show();\r\n            $('#content-wrapper').removeClass('expand');\r\n        } else {\r\n            currentElement.removeClass('large-back');\r\n            currentElement.addClass('large-next');\r\n            currentElement.attr({ title: 'Show Left Navigation' });\r\n            $('#left-navigation').hide();\r\n            $('#content-wrapper').addClass('expand');\r\n        }\r\n    }\r\n\r\n    function updateLeftNavigationSetting(isShow) {\r\n        $.ajax({\r\n            type: 'POST',\r\n            url: _global.root + 'Employee/ToogleLeftNavigation',\r\n            data: { isShow: isShow }\r\n        });\r\n    }\r\n\r\n    if (_global.isShowLeftNavigation === 'True') {\r\n        toggleLeftNavigation(true);\r\n    } else {\r\n        toggleLeftNavigation(false);\r\n    }\r\n\r\n    $('#searchIcon').on('click', function () {\r\n        document.location = _global.root + 'employee/index?query=' + $('#searchbox').val();\r\n    });\r\n\r\n    $('#searchbox').keyup(function (event) {\r\n        if (event.keyCode === 13) {\r\n            $('#searchIcon').trigger('click');\r\n        }\r\n    });\r\n\r\n    $('#toggle-left-navigation').bind('click', function () {\r\n        let currentElement = $(this);\r\n        if (currentElement.hasClass('large-back')) {\r\n            toggleLeftNavigation(false);\r\n            updateLeftNavigationSetting(false);\r\n        } else {\r\n            toggleLeftNavigation(true);\r\n            updateLeftNavigationSetting(true);\r\n        }\r\n\r\n        $('.content_scroll').scroll(updateTableHeaders).trigger('scroll');\r\n        $(window).resize(function () {\r\n            updateTableHeaders();\r\n        });\r\n    });\r\n\r\n    let selectNavItem = $('#' + $('#CurrentUrlSelected').val());\r\n    if (selectNavItem !== undefined) {\r\n        selectNavItem.addClass('selected');\r\n    }\r\n\r\n    //show/hide navigation section\r\n    $('div.togglable_section').bind('click', function () {\r\n        let currentSection = $(this);\r\n        let divItems = currentSection.next('div.navItem');\r\n        if (currentSection.hasClass('folded')) {\r\n            currentSection.removeClass('folded');\r\n            divItems.show(200);\r\n        } else {\r\n            currentSection.addClass('folded');\r\n            divItems.hide(200);\r\n        }\r\n    });\r\n\r\n    // add style for first item section\r\n    $('div.togglable_section:first-child').children(':first').addClass('first');\r\n\r\n    $('.el[data-hashovermenu=True], .el[data-hashovermenu=data-hashovermenu]').hover(\r\n        function () {\r\n            $(this).find('.hoveraction').fadeIn(400);\r\n        }, function () {\r\n            $(this).find('.hoveraction').hide();\r\n        }\r\n    );\r\n});","/*!\n * jQuery JavaScript Library v3.4.1\n * https://jquery.com/\n *\n * Includes Sizzle.js\n * https://sizzlejs.com/\n *\n * Copyright JS Foun